<?php
require_once __DIR__.'/../config/app.php';
require_role('member');
$user=current_user();
$pageTitle='My profile';
$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    $name=trim($_POST['name']??'');
    if($name===''){$msg='Please enter your name.';}else{
        $pdo->prepare('UPDATE users SET name=? WHERE id=?')->execute([$name,$user['id']]);
        $_SESSION['user']['name']=$name;$user['name']=$name;$msg='Your profile has been updated.';
    }
}
$stats=['visits'=>0,'plans'=>0,'records'=>0];
try{$q=$pdo->prepare('SELECT COUNT(*) FROM attendance WHERE user_id=? AND check_in >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)');$q->execute([$user['id']]);$stats['visits']=(int)$q->fetchColumn();}catch(Throwable $e){}
try{$q=$pdo->prepare('SELECT COUNT(*) FROM workout_plans WHERE member_id=?');$q->execute([$user['id']]);$stats['plans']=(int)$q->fetchColumn();}catch(Throwable $e){}
try{$q=$pdo->prepare('SELECT COUNT(*) FROM progress_records WHERE member_id=?');$q->execute([$user['id']]);$stats['records']=(int)$q->fetchColumn();}catch(Throwable $e){}
$level=$stats['visits']>=16?'Consistent Athlete':($stats['visits']>=8?'Active Member':($stats['visits']>=3?'Getting Stronger':'Fitness Starter'));
$levelDesc=$stats['visits']>=16?'Excellent consistency. Keep building sustainable habits.':($stats['visits']>=8?'Good momentum. Keep your weekly routine steady.':($stats['visits']>=3?'You are building a routine. Every session counts.':'Start with manageable sessions and build consistency.'));
$levelPct=min(100,(int)round($stats['visits']/20*100));
$levelImage=$stats['visits']>=16?'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=1200&q=85':($stats['visits']>=8?'https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?auto=format&fit=crop&w=1200&q=85':'https://images.unsplash.com/photo-1517836357463-d25dfeac3438?auto=format&fit=crop&w=1200&q=85');
include __DIR__.'/../includes/header.php';
?>
