</main></div>
<script>
(()=>{const tabs=[...document.querySelectorAll('.profile-tab')];const panels=[...document.querySelectorAll('.profile-tab-panel')];function activate(name){tabs.forEach(t=>{const on=t.dataset.tab===name;t.classList.toggle('active',on);t.setAttribute('aria-selected',on?'true':'false');});panels.forEach(p=>{const on=p.id==='profile-'+name;p.hidden=!on;p.classList.toggle('active',on);});}tabs.forEach(t=>t.addEventListener('click',()=>activate(t.dataset.tab)));})();
</script><script src="<?= BASE_URL ?>/assets/js/main.js"></script></body></html>
